+class ContactForm {
+    constructor(formId) {
+        this.form = document.getElementById(formId);
+        this.fields = {
+            fullName: document.getElementById('fullName'),
+            email: document.getElementById('email'),
+            phone: document.getElementById('phone')
+        };
+        this.errors = {
+            fullName: document.getElementById('fullNameError'),
+            email: document.getElementById('emailError'),
+            phone: document.getElementById('phoneError')
+        };
+        this.successMessage = document.getElementById('successMessage');
+        this.isValidated = false;
+
+        this.setupEventListeners();
+    }
+
+    setupEventListeners() {
+        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+        
+        Object.entries(this.fields).forEach(([key, field]) => {
+            field.addEventListener('blur', () => {
+                if (this.isValidated) {
+                    this.validateField(key);
+                }
+            });
+
+            field.addEventListener('input', () => {
+                if (this.isValidated && this.errors[key].classList.contains('show')) {
+                    this.validateField(key);
+                }
+            });
+        });
+    }
+
+    validateField(fieldName) {
+        const field = this.fields[fieldName];
+        const errorElement = this.errors[fieldName];
+        let isValid = true;
+        let errorMessage = '';
+
+        if (fieldName === 'fullName') {
+            if (!field.value.trim()) {
+                isValid = false;
+                errorMessage = 'Full name is required';
+            } else if (field.value.trim().length < 2) {
+                isValid = false;
+                errorMessage = 'Full name must be at least 2 characters';
+            }
+        } else if (fieldName === 'email') {
+            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+            if (!field.value.trim()) {
+                isValid = false;
+                errorMessage = 'Email address is required';
+            } else if (!emailRegex.test(field.value.trim())) {
+                isValid = false;
+                errorMessage = 'Please enter a valid email address';
+            }
+        } else if (fieldName === 'phone') {
+            if (field.value.trim()) {
+                const phoneRegex = /^[\d\s\-\+\(\)\.]+$/;
+                if (!phoneRegex.test(field.value.trim())) {
+                    isValid = false;
+                    errorMessage = 'Phone number contains invalid characters';
+                } else if (field.value.replace(/\D/g, '').length < 10) {
+                    isValid = false;
+                    errorMessage = 'Phone number must contain at least 10 digits';
+                }
+            }
+        }
+
+        if (isValid) {
+            field.classList.remove('has-error');
+            errorElement.classList.remove('show');
+            errorElement.textContent = '';
+        } else {
+            field.classList.add('has-error');
+            errorElement.classList.add('show');
+            errorElement.textContent = errorMessage;
+        }
+
+        return isValid;
+    }
+
+    validateForm() {
+        let isValid = true;
+        Object.keys(this.fields).forEach(fieldName => {
+            if (!this.validateField(fieldName)) {
+                isValid = false;
+            }
+        });
+        return isValid;
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+        this.isValidated = true;
+
+        if (this.validateForm()) {
+            this.submitForm();
+        }
+    }
+
+    submitForm() {
+        const formData = {
+            fullName: this.fields.fullName.value.trim(),
+            email: this.fields.email.value.trim(),
+            phone: this.fields.phone.value.trim()
+        };
+
+        console.log('Form submitted:', formData);
+
+        this.form.style.display = 'none';
+        this.successMessage.style.display = 'flex';
+
+        setTimeout(() => {
+            this.resetForm();
+        }, 3000);
+    }
+
+    resetForm() {
+        this.form.reset();
+        this.form.style.display = 'flex';
+        this.successMessage.style.display = 'none';
+        this.isValidated = false;
+
+        Object.entries(this.errors).forEach(([key, errorElement]) => {
+            errorElement.classList.remove('show');
+            errorElement.textContent = '';
+        });
+
+        Object.values(this.fields).forEach(field => {
+            field.classList.remove('has-error');
+        });
+    }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+    new ContactForm('contactForm');
+});
+
